'use strict';
// On-page cinema: scenes that happen to the website itself (shadows over the page, dust from the title, the interface
// collapsing into a dot). Only transforms and opacity are animated, every element is removed afterwards, each scene is
// skippable, and reduced motion turns them into short still captions. Purely visual: no scene grants anything.
(()=>{
 const G=JustinGame,el=id=>document.getElementById(id),stage=el('stage');
 const reduced=()=>el('gentle')?.checked||matchMedia('(prefers-reduced-motion: reduce)').matches;
 const sfx=kind=>window.JustinGUIAudio?.play(kind);
 const face=id=>{const skin=G.skins.find(s=>s.id===id),S=window.JustinSprites;if(!S)return 'assets/friend.png';return S.url(S.ready(skin)?skin:G.skins[0])||'assets/friend.png'};
 const preload=ids=>{for(const id of ids)window.JustinSprites?.ready(G.skins.find(s=>s.id===id))};
 const rand=(a,b)=>a+Math.random()*(b-a);
 const ABORT=Symbol('skip');
 const root=document.createElement('div');root.id='cinema';root.hidden=true;root.setAttribute('aria-live','polite');document.body.append(root);
 const skipButton=document.createElement('button');skipButton.type='button';skipButton.className='cinema-skip';skipButton.textContent='Skip ›';
 let current=null,chain=Promise.resolve();

 /* ---------- runner ---------- */
 function run(name,scene,{block=false}={}){const job=chain.then(()=>play(name,scene,block));chain=job.catch(()=>{});return job}
 async function play(name,scene,block){const token={alive:true,anims:[],timers:[],frames:[],cleanup:[]};current=token;root.hidden=false;root.className='cinema-'+name+(block?' blocking':'');root.replaceChildren(skipButton);skipButton.onclick=()=>{token.alive=false;token.wake?.()};
  try{await scene(token)}catch(error){if(error!==ABORT)console.error(error)}finally{for(const a of token.anims)try{a.cancel()}catch{}for(const t of token.timers)clearTimeout(t);for(const f of token.frames)cancelAnimationFrame(f);for(const c of token.cleanup)try{c()}catch{}root.replaceChildren();root.hidden=true;root.className='';music(true,0);current=null}}
 function step(token,ms){return new Promise((resolve,reject)=>{if(!token.alive){reject(ABORT);return}const t=setTimeout(()=>{token.wake=null;token.alive?resolve():reject(ABORT)},ms);token.timers.push(t);token.wake=()=>{clearTimeout(t);reject(ABORT)}})}
 function at(token,ms,fn){token.timers.push(setTimeout(()=>{if(token.alive)fn()},ms))}
 function add(token,cls,html='',parent=root){const e=document.createElement('div');e.className=cls;if(html)e.innerHTML=html;parent.append(e);return e}
 function img(token,src,cls,parent=root){const i=document.createElement('img');i.src=src;i.alt='';i.className=cls;i.decoding='async';parent.append(i);return i}
 function anim(token,target,frames,options){if(!target?.animate)return null;const a=target.animate(frames,{fill:'forwards',...options});token.anims.push(a);return a}
 function pos(e,x,y){e.style.transform='translate3d('+x+'px,'+y+'px,0)'}
 const page=()=>[document.querySelector('body>header'),el('name'),document.querySelector('.ranked-note'),document.querySelector('.clicker-layout'),document.querySelector('body>footer')].filter(Boolean);
 function shake(token,power=6,ms=300){for(const e of page().slice(0,4))anim(token,e,[{transform:'translate(0,0)'},{transform:'translate('+(-power)+'px,'+power*.6+'px)'},{transform:'translate('+power+'px,'+(-power*.5)+'px)'},{transform:'translate('+(-power*.5)+'px,'+power*.3+'px)'},{transform:'translate(0,0)'}],{duration:ms,easing:'ease-out',fill:'none'})}
 function camera(token,frames,options){const layout=document.querySelector('.clicker-layout');return anim(token,layout,frames,options)}
 let musicVolume=null;function music(on,ms=500){const a=el('audio');if(!a||a.paused)return;if(!on&&musicVolume===null)musicVolume=a.volume;const from=a.volume,to=on?(musicVolume??from):0,t0=performance.now();if(!ms){a.volume=to;if(on)musicVolume=null;return}const tick=()=>{const k=Math.min(1,(performance.now()-t0)/ms);a.volume=from+(to-from)*k;if(k<1)requestAnimationFrame(tick);else if(on)musicVolume=null};tick()}
 function letterbox(token){const top=add(token,'cine-bar top'),bottom=add(token,'cine-bar bottom');anim(token,top,[{transform:'translateY(-100%)'},{transform:'none'}],{duration:350,easing:'ease-out'});anim(token,bottom,[{transform:'translateY(100%)'},{transform:'none'}],{duration:350,easing:'ease-out'});return ()=>{anim(token,top,[{transform:'none'},{transform:'translateY(-100%)'}],{duration:300});anim(token,bottom,[{transform:'none'},{transform:'translateY(100%)'}],{duration:300})}}
 function stageCenter(){const r=stage.getBoundingClientRect(),f=window.justinFace?.()||{x:r.width/2,y:r.height/2,size:120};return {x:r.x+f.x,y:r.y+f.y,size:f.size,rect:r}}
 function caption(token,title,sub,cls=''){const c=add(token,'cine-caption '+cls,'<b></b>'+(sub?'<span></span>':''));c.querySelector('b').textContent=title;if(sub)c.querySelector('span').textContent=sub;anim(token,c,[{opacity:0,transform:'translate(-50%,-50%) scale(1.8) rotate(-4deg)'},{opacity:1,transform:'translate(-50%,-50%) scale(1) rotate(-2deg)'}],{duration:450,easing:'cubic-bezier(.2,.9,.3,1.4)'});return c}
 async function still(token,title,sub,ms=1600){caption(token,title,sub);await step(token,ms)}

 /* ---------- shared props ---------- */
 function mothership(parent=root){const m=document.createElement('div');m.className='cine-mothership';m.innerHTML='<div class="ms-dome"></div><div class="ms-body"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="ms-hatch"><img alt="" src="'+face('normal')+'"></div>';parent.append(m);return m}
 function portal(token,x,y,size){const p=add(token,'cine-portal');p.style.width=p.style.height=size+'px';p.style.left=x-size/2+'px';p.style.top=y-size/2+'px';anim(token,p,[{transform:'scale(0) rotate(0)'},{transform:'scale(1) rotate(180deg)'}],{duration:320,easing:'ease-out'});return p}
 function cracks(token,rect,color='#3dff9a'){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','cine-cracks');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('preserveAspectRatio','none');svg.style.left=rect.x+'px';svg.style.top=rect.y+'px';svg.style.width=rect.width+'px';svg.style.height=rect.height+'px';
  for(let i=0;i<7;i++){let x=50+rand(-6,6),y=50+rand(-6,6),d='M'+x+' '+y;const a=i/7*Math.PI*2+rand(-.3,.3);for(let k=0;k<5;k++){x+=Math.cos(a+rand(-.6,.6))*rand(6,11);y+=Math.sin(a+rand(-.6,.6))*rand(6,11);d+=' L'+x.toFixed(1)+' '+y.toFixed(1)}const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);path.setAttribute('stroke',color);path.setAttribute('pathLength','1');svg.append(path);anim(token,path,[{strokeDashoffset:1},{strokeDashoffset:0}],{duration:1100,delay:i*60,easing:'ease-out'})}root.append(svg);return svg}
 function fragments(token,x,y,color,count=8){for(let i=0;i<count;i++){const f=add(token,'cine-shard');f.style.left=x+'px';f.style.top=y+'px';f.style.background=color;const a=rand(0,Math.PI*2),d=rand(50,130);anim(token,f,[{transform:'translate(-50%,-50%) rotate(0) scale(1)',opacity:1},{transform:'translate(calc(-50% + '+Math.cos(a)*d+'px),calc(-50% + '+(Math.sin(a)*d+40)+'px)) rotate('+rand(-400,400)+'deg) scale(.4)',opacity:0}],{duration:rand(500,800),easing:'cubic-bezier(.2,.7,.4,1)'})}}

 /* ---------- cinematic language shared by the invasion entrances ---------- */
 const trailer={swarm:['THEY’RE HERE.','TINY JUSTIN SWARM'],giant:['HE IS ENORMOUS.','GIANT JUSTIN'],loki:['TIME IS BROKEN.','LOKI INVASION'],ufo:['WE ARE NOT ALONE.','UFO INVASION']};
 function cue(token,variant,riserAt,bars=true){const v=add(token,'cine-vignette');anim(token,v,[{opacity:0},{opacity:1}],{duration:700});if(bars){token.bars=letterbox(token)}if(riserAt!=null)at(token,riserAt,()=>sfx('riser'))}
 function slam(token,variant){sfx('boom');const [line,sub]=trailer[variant],card=document.createElement('div');card.className='cine-title floating';card.setAttribute('aria-hidden','true');card.innerHTML='<b></b><span></span>';document.body.append(card);setTimeout(()=>card.remove(),1600);card.querySelector('b').textContent=line;card.querySelector('span').textContent=sub;card.animate([{opacity:0,transform:'translate(-50%,-50%) scale(1.25)',letterSpacing:'.5em'},{opacity:1,transform:'translate(-50%,-50%) scale(1)',letterSpacing:'.08em',offset:.25},{opacity:1,transform:'translate(-50%,-50%) scale(.98)',offset:.8},{opacity:0,transform:'translate(-50%,-50%) scale(.96)'}],{duration:1500,easing:'ease-out',fill:'forwards'});const flash=add(token,'cine-flash');anim(token,flash,[{opacity:.65},{opacity:0}],{duration:420,easing:'ease-out'});if(token.bars)at(token,700,()=>token.bars())}

 /* ---------- countdown teasers: small, non-blocking hints of what is coming ---------- */
 let lastTease=0;function tease(variant){if(reduced()||performance.now()-lastTease<2500||current)return;lastTease=performance.now();const r=stage.getBoundingClientRect(),bits=[];const temp=(cls,html='')=>{const e=document.createElement('div');e.className='tease '+cls;e.innerHTML=html;stage.append(e);bits.push(e);return e};setTimeout(()=>bits.forEach(b=>b.remove()),1800);
  if(variant==='swarm'){const h=temp('tease-peek','<img alt="" src="'+face('normal')+'">');h.style.left=rand(10,85)+'%';h.animate([{transform:'translateY(100%)'},{transform:'translateY(15%)',offset:.35},{transform:'translateY(15%)',offset:.7},{transform:'translateY(100%)'}],{duration:1500,easing:'ease-in-out'});sfx('squish')}
  if(variant==='giant'){stage.animate([{transform:'translate(0,0)'},{transform:'translate(-4px,3px)'},{transform:'translate(4px,-2px)'},{transform:'translate(0,0)'}],{duration:260});sfx('thud');for(let i=0;i<7;i++){const d=temp('tease-dust');d.style.left=rand(5,95)+'%';d.animate([{transform:'translateY(0)',opacity:.9},{transform:'translateY('+rand(60,r.height*.6)+'px)',opacity:0}],{duration:rand(800,1400),delay:rand(0,200),easing:'ease-in',fill:'both'})}}
  if(variant==='loki'){const g=temp('tease-glitch');g.animate([{opacity:0},{opacity:.55},{opacity:0},{opacity:.4},{opacity:0}],{duration:600,easing:'steps(5)'});sfx('glitch')}
  if(variant==='ufo'){const l=temp('tease-light');l.animate([{transform:'translateX(-20px)'},{transform:'translateX('+(r.width+40)+'px)'}],{duration:1100,easing:'linear'});sfx('beam')}}

 /* ---------- invasion intros (~4s) ---------- */
 const intros={
  async swarm(token,o){music(false,600);cue(token,'swarm',1150,false);const end=letterbox(token),W=innerWidth,H=innerHeight,src=face('normal');
   const peek=img(token,src,'cine-tiny');peek.style.left=W*.3+'px';peek.style.top=H+'px';anim(token,peek,[{transform:'translateY(0)'},{transform:'translateY(-44px)',offset:.35},{transform:'translateY(-44px)',offset:.75},{transform:'translateY(0)'}],{duration:1400,easing:'ease-in-out'});
   await step(token,1400);sfx('rumble');shake(token,2,1400);const edges=[[0,H*.3],[W-46,H*.55],[W*.62,0],[0,H*.72],[W-46,H*.18],[W*.18,0]],heads=[];
   for(const [i,[x,y]] of edges.entries()){at(token,100+i*130,()=>{const h=img(token,src,'cine-tiny still');pos(h,x,y);heads.push([h,x,y])})}
   await step(token,1300);const r=stage.getBoundingClientRect();camera(token,[{transform:'scale(1)'},{transform:'scale(.93)'}],{duration:450,easing:'ease-out'});
   for(let i=0;i<22;i++){const [h,x,y]=heads[i]||[img(token,src,'cine-tiny'),...(()=>{const e=edges[i%edges.length];return [e[0]+rand(-30,30),e[1]+rand(-30,30)]})()];if(!heads[i])pos(h,x,y);anim(token,h,[{transform:'translate3d('+x+'px,'+y+'px,0) rotate(0)',opacity:1},{transform:'translate3d('+(r.x+rand(.15,.85)*r.width)+'px,'+(r.y+rand(.2,.8)*r.height)+'px,0) rotate('+rand(-40,40)+'deg)',opacity:1,offset:.8},{transform:'translate3d('+(r.x+r.width/2)+'px,'+(r.y+r.height/2)+'px,0) scale(.3)',opacity:0}],{duration:900,delay:i*28,easing:'cubic-bezier(.3,.6,.4,1)'})}
   await step(token,450);sfx('hit');slam(token,'swarm');o.onSlam?.();await step(token,500);camera(token,[{transform:'scale(.93)'},{transform:'scale(1)'}],{duration:300});end();music(true,400);await step(token,350)},
  async giant(token,o){music(false,500);cue(token,'giant',2300);const W=innerWidth,H=innerHeight,shadow=add(token,'cine-shadow');anim(token,shadow,[{transform:'translateX(-130vw)'},{transform:'translateX(130vw)'}],{duration:1300,easing:'linear'});sfx('whoosh');
   at(token,850,()=>{const t=el('name').getBoundingClientRect();anim(token,el('name'),[{transform:'rotate(-3deg)'},{transform:'rotate(-3deg) translate(2px,1px)'},{transform:'rotate(-3deg)'}],{duration:180,iterations:3,fill:'none'});for(let i=0;i<14;i++){const d=add(token,'cine-dust');d.style.left=t.x+rand(.05,.95)*t.width+'px';d.style.top=t.bottom-6+'px';anim(token,d,[{transform:'translateY(0)',opacity:.9},{transform:'translateY('+rand(60,140)+'px)',opacity:0}],{duration:rand(700,1100),delay:rand(0,250),easing:'ease-in'})}});
   await step(token,1300);sfx('thud');shake(token,9,280);await step(token,600);sfx('thud');shake(token,12,320);await step(token,400);
   const g=add(token,'inv-giant cine-giant','<img alt="" src="'+face('normal')+'"><i class="lid l"></i><i class="lid r"></i>');camera(token,[{transform:'translateY(0)'},{transform:'translateY(12vh)'}],{duration:900,easing:'ease-in-out'});anim(token,g,[{transform:'translate(-50%,100%)'},{transform:'translate(-50%,22%)'}],{duration:1100,easing:'cubic-bezier(.25,.6,.3,1)'});
   await step(token,1250);await step(token,450);g.classList.add('blink');await step(token,170);g.classList.remove('blink');await step(token,150);sfx('impact');shake(token,10,350);slam(token,'giant');o.onSlam?.();camera(token,[{transform:'translateY(12vh)'},{transform:'translateY(0)'}],{duration:350,easing:'ease-out'});music(true,600);await step(token,380)},
  async loki(token,o){music(false,250);cue(token,'loki',1700);const r=stage.getBoundingClientRect(),c=stageCenter(),clock=add(token,'cine-clock','<b>00:01</b>');
   for(const [i,k] of ['deep1','deep2','deep3'].entries()){sfx(k);clock.classList.remove('jolt');void clock.offsetWidth;clock.classList.add('jolt');if(i===0)cracks(token,r);await step(token,520)}
   anim(token,clock,[{opacity:1},{opacity:0,transform:'translate(-50%,-50%) scale(1.4)'}],{duration:250});const copies=[];for(let i=0;i<4;i++){const cp=img(token,face(window.justinClicker.skin?.id||'loki'),'cine-copy');cp.style.width=c.size*.9+'px';pos(cp,c.x-c.size*.45,c.y-c.size*.7);copies.push(cp);anim(token,cp,[{transform:'translate3d('+(c.x-c.size*.45)+'px,'+(c.y-c.size*.7)+'px,0)',opacity:.35},{transform:'translate3d('+(c.x-c.size*.45+(i-1.5)*26)+'px,'+(c.y-c.size*.7)+'px,0)',opacity:.8}],{duration:400,easing:'ease-out'})}
   await step(token,500);for(const [i,cp] of copies.entries())anim(token,cp,[{transform:cp.style.transform+' translateX('+(i-1.5)*26+'px)'},{transform:'translate3d('+(c.x-c.size*.45+(i-1.5)*26)+'px,'+(c.y-c.size*.7)+'px,0) scale(1.12)'}],{duration:180});
   await step(token,320);const W=innerWidth,H=innerHeight;for(const cp of copies){const x=rand(60,W-60),y=rand(90,H-120);portal(token,x,y,90);sfx('portal');anim(token,cp,[{transform:'translate3d('+(c.x-c.size*.45)+'px,'+(c.y-c.size*.7)+'px,0) scale(1)',opacity:.85},{transform:'translate3d('+(x-c.size*.45)+'px,'+(y-c.size*.7)+'px,0) scale(.05)',opacity:0}],{duration:520,easing:'cubic-bezier(.5,0,.8,.6)'})}
   await step(token,700);const p=portal(token,W/2,H/2,190);const real=img(token,face('loki'),'cine-loki');anim(token,real,[{transform:'translate(-50%,-50%) scale(.2) translateY(30px)',opacity:0},{transform:'translate(-50%,-50%) scale(1)',opacity:1}],{duration:420,easing:'cubic-bezier(.2,.9,.3,1.3)'});
   await step(token,380);music(true,0);sfx('hit');slam(token,'loki');o.onSlam?.();await step(token,380);anim(token,p,[{transform:'scale(1)'},{transform:'scale(0) rotate(-180deg)'}],{duration:300});anim(token,real,[{opacity:1},{opacity:0}],{duration:250});await step(token,260)},
  async ufo(token,o){music(false,600);cue(token,'ufo',1100);const W=innerWidth,H=innerHeight,light=add(token,'cine-light');anim(token,light,[{transform:'translate(-10vw,'+H*.12+'px)'},{transform:'translate(110vw,'+H*.2+'px)'}],{duration:950,easing:'linear'});
   await step(token,900);const shadow=add(token,'cine-ufo-shadow');anim(token,shadow,[{transform:'translateX(-50%) scale(0)',opacity:0},{transform:'translateX(-50%) scale(1)',opacity:1}],{duration:700,easing:'ease-out'});await step(token,350);sfx('hum');
   const m=mothership();anim(token,m,[{transform:'translate(-50%,-130%)'},{transform:'translate(-50%,0)'}],{duration:1250,easing:'cubic-bezier(.2,.7,.3,1)'});await step(token,1300);m.classList.add('open');const spot=add(token,'cine-spotlight','',m);
   await step(token,550);m.classList.add('beam');sfx('beam');slam(token,'ufo');o.onSlam?.();o.deploy?.(m);await step(token,500);music(true,500);await step(token,150)}
 };

 /* ---------- invasion endings (~2s) ---------- */
 const outros={
  async swarm(token,o){const W=innerWidth,H=innerHeight,door=add(token,'cine-door','<i></i>'),dx=W-Math.min(110,W*.2),dy=H-150;door.style.left=dx+'px';door.style.top=dy+'px';
   const runners=(o.points?.length?o.points:[[W*.3,H*.4],[W*.5,H*.3],[W*.4,H*.6]]).slice(0,10);door.classList.add('open');
   runners.forEach(([x,y],i)=>{const h=img(token,face('normal'),'cine-tiny');const last=i===runners.length-1;anim(token,h,last?[{transform:'translate3d('+x+'px,'+y+'px,0)'},{transform:'translate3d('+(dx+6)+'px,'+(dy+20)+'px,0)',offset:.45},{transform:'translate3d('+(dx+6)+'px,'+(dy+20)+'px,0) scale(1.15,.8)',offset:.55},{transform:'translate3d('+(dx+6)+'px,'+(dy+20)+'px,0) scale(.8,1.2)',offset:.65},{transform:'translate3d('+(dx+6)+'px,'+(dy+20)+'px,0) scale(1.2,.75)',offset:.78},{transform:'translate3d('+(dx+14)+'px,'+(dy+24)+'px,0) scale(0)'}]:[{transform:'translate3d('+x+'px,'+y+'px,0)'},{transform:'translate3d('+(dx+10)+'px,'+(dy+26)+'px,0) scale(.3)',opacity:.4}],{duration:last?1500:rand(600,950),delay:last?120:i*45,easing:'ease-in'})});
   await step(token,1580);sfx('pop');await step(token,180);door.classList.remove('open');sfx('thud');await step(token,240)},
  async giant(token,o){const g=o.giant||add(token,'inv-giant cine-giant','<img alt="" src="'+face('normal')+'">');if(o.giant){g.classList.add('cine-giant');root.append(g)}g.classList.remove('flinch','defeated');anim(token,g,[{transform:'translate(-50%,22%) perspective(900px) rotateX(0)'},{transform:'translate(-50%,40%) perspective(900px) rotateX(-70deg)',opacity:1,offset:.85},{transform:'translate(-50%,75%) perspective(900px) rotateX(-88deg)',opacity:0}],{duration:950,easing:'ease-in'});
   await step(token,1750);sfx('crash');shake(token,3,240);await step(token,250)},
  async loki(token,o){const W=innerWidth,H=innerHeight;for(const [x,y] of o.decoys||[])fragments(token,x,y,'#3dff9a',10);if(o.decoys?.length)sfx('shatter');
   const [rx,ry]=o.real||[W*.4,H*.5],px=W*.84,py=H*.5,p=portal(token,px,py,170),loki=img(token,face('loki'),'cine-loki small');
   anim(token,loki,[{transform:'translate3d('+(rx-50)+'px,'+(ry-70)+'px,0)'},{transform:'translate3d('+(px-50)+'px,'+(py-70)+'px,0) scale(.9)',offset:.55},{transform:'translate3d('+(px-50)+'px,'+(py-70)+'px,0) rotate(8deg)',offset:.7},{transform:'translate3d('+(px-50)+'px,'+(py-70)+'px,0) rotate(-8deg)',offset:.85},{transform:'translate3d('+(px-50)+'px,'+(py-70)+'px,0) rotate(5deg)'}],{duration:1500,easing:'ease-in-out'});
   at(token,700,()=>{anim(token,p,[{transform:'scale(1)'},{transform:'scale(.42) rotate(160deg)'}],{duration:450,easing:'cubic-bezier(.5,0,.3,1.4)'});sfx('portal')});await step(token,1600);sfx('pop');await step(token,350)},
  async ufo(token,o){const W=innerWidth,H=innerHeight,m=o.mothership||mothership();if(o.mothership)root.append(m);m.classList.remove('beam');const w=m.getBoundingClientRect().width||W*.6,h=w*.32;sfx('powerdown');
   const a=anim(token,m,[{transform:'translate(-50%,0)'},{transform:'translate(-50%,-30px) scale(.8)',offset:.15},{transform:'translate(-50%,10px) scale(.8) rotate(6deg)',offset:.3},{transform:'translate('+(W/2-w*.4-W/2)+'px,'+(H*.45)+'px) scale(.5) rotate(-4deg)',offset:.55},{transform:'translate('+(-W*.48)+'px,'+(H*.15)+'px) scale(.45)',offset:.78},{transform:'translate('+(-W*.2)+'px,'+(-H*.5)+'px) scale(.4)'}],{duration:1900,easing:'linear'});at(token,300,()=>m.classList.add('dead'));at(token,1050,()=>sfx('thud'));at(token,1480,()=>sfx('thud'));await step(token,1950)}
 };

 /* ---------- rebirth: collapse and return (~6s) ---------- */
 async function rebirth(token,info){const c=stageCenter(),W=innerWidth,H=innerHeight;
  if(reduced()){await still(token,info.mult+'× FOREVER','Rebirth '+info.rebirths+' · points and upgrades reset',2200);return}
  music(false,800);const dark=add(token,'cine-dark');anim(token,dark,[{opacity:0},{opacity:1}],{duration:1800,delay:500});
  const icons=['coin','upgrade-finger','upgrade-mouse','upgrade-chat','upgrade-factory','upgrade-reactor','upgrade-keyboard','upgrade-time','gift','bolt','coin','upgrade-satellite'],orbit=icons.map((name,i)=>{const e=img(token,'assets/icons/'+name+'.svg','cine-orbit');e.dataset.a=String(i/icons.length*Math.PI*2);return e});
  for(let i=0;i<4;i++){const n=add(token,'cine-orbit-num');n.textContent='+'+Math.floor(rand(1,999)).toLocaleString();orbit.push(n);n.dataset.a=String(rand(0,6.28))}
  for(const e of page()){const r=e.getBoundingClientRect();e.style.transformOrigin=(c.x-r.x)+'px '+(c.y-r.y)+'px';anim(token,e,[{transform:'scale(1)',opacity:1},{transform:'scale(.02)',opacity:0}],{duration:1600,delay:600,easing:'cubic-bezier(.6,0,.9,.5)'})}
  token.cleanup.push(()=>{for(const e of page())e.style.transformOrigin=''});
  const t0=performance.now(),R=Math.min(W,H)*.4;let spin=0;const loop=now=>{const k=Math.min(1,(now-t0)/2200),r=R*(1-k*k);spin+=(2+16*k*k)*.016;for(const e of orbit){const a=Number(e.dataset.a)+spin;e.style.transform='translate3d('+(c.x+Math.cos(a)*r-16)+'px,'+(c.y+Math.sin(a)*r*.8-16)+'px,0) scale('+(1-k*.8)+')';e.style.opacity=String(1-k*.6)}if(k<1&&token.alive)token.frames.push(requestAnimationFrame(loop))};token.frames.push(requestAnimationFrame(loop));sfx('whoosh');sfx('riser');
  await step(token,2200);for(const e of orbit)e.remove();const dot=add(token,'cine-dot');dot.style.left=c.x+'px';dot.style.top=c.y+'px';
  await step(token,700);sfx('boom');sfx('gong');sfx('reveal-epic');const ring=add(token,'cine-ring');ring.style.left=c.x+'px';ring.style.top=c.y+'px';anim(token,ring,[{transform:'translate(-50%,-50%) scale(0)',opacity:1},{transform:'translate(-50%,-50%) scale(60)',opacity:0}],{duration:800,easing:'ease-out'});anim(token,dot,[{transform:'translate(-50%,-50%) scale(1)'},{transform:'translate(-50%,-50%) scale(6)',opacity:0}],{duration:300});anim(token,dark,[{opacity:1},{opacity:0}],{duration:450});
  page().forEach((e,i)=>anim(token,e,[{transform:'scale(.02)',opacity:0},{transform:'scale(1.03)',opacity:1,offset:.8},{transform:'scale(1)',opacity:1}],{duration:700,delay:i*70,easing:'ease-out'}));
  await step(token,650);music(true,800);const stamp=caption(token,info.mult+'× FOREVER','Rebirth '+info.rebirths,'big');sfx('hit');await step(token,750);
  const list=add(token,'cine-chips');for(const [i,text] of [['Points','0'],['Upgrades','0'],['Purchased Justins','0'],['Roll-only Justins','kept · '+info.kept]].entries()){at(token,i*260,()=>{const chip=add(token,'cine-chip','<span></span><b></b>',list);chip.querySelector('span').textContent=text[0];chip.querySelector('b').textContent=text[1];anim(token,chip,[{transform:'translateY(14px)',opacity:0},{transform:'none',opacity:1}],{duration:260,easing:'ease-out'});sfx('tick')})}
  await step(token,2300);anim(token,stamp,[{opacity:1},{opacity:0}],{duration:350});anim(token,list,[{opacity:1},{opacity:0}],{duration:350});await step(token,380)}

 /* ---------- collection milestone: the final piece (~3.4s) ---------- */
 async function collection(token,info){const W=innerWidth,H=innerHeight,cx=W/2,cy=H/2;if(reduced()){await still(token,info.count+' JUSTINS COLLECTED','your collection gift is ready',1800);return}
  const dark=add(token,'cine-dark soft');anim(token,dark,[{opacity:0},{opacity:1}],{duration:300});const wheel=add(token,'cine-wheel');wheel.style.left=cx+'px';wheel.style.top=cy+'px';
  const ids=info.owned.filter(id=>id!==info.newest).slice(-15),n=ids.length+1,R=Math.min(W,H)*.3,size=Math.max(46,Math.min(84,R*.5));
  ids.forEach((id,i)=>{const a=(i+1)/n*Math.PI*2-Math.PI/2,x=Math.cos(a)*R,y=Math.sin(a)*R,p=img(token,face(id),'cine-portrait',wheel);p.style.width=size+'px';const fx=rand(-1,1)*W,fy=(Math.random()<.5?-1:1)*H;anim(token,p,[{transform:'translate('+fx+'px,'+fy+'px) translate(-50%,-50%) rotate(-30deg)'},{transform:'translate('+x+'px,'+y+'px) translate(-50%,-50%)'}],{duration:650,delay:i*35,easing:'cubic-bezier(.2,.8,.3,1)'})});
  const spin=anim(token,wheel,[{transform:'rotate(0)'},{transform:'rotate(360deg)'}],{duration:2600,iterations:Infinity,easing:'linear',fill:'none'});sfx('musicbox');
  await step(token,1100);const newest=img(token,face(info.newest),'cine-portrait newest',wheel);newest.style.width=size*1.1+'px';const top=-Math.PI/2;anim(token,newest,[{transform:'translate('+W+'px,'+(-R)+'px) translate(-50%,-50%)'},{transform:'translate('+Math.cos(top)*R+'px,'+Math.sin(top)*R+'px) translate(-50%,-50%)'}],{duration:620,easing:'cubic-bezier(.2,.9,.3,1.2)'});
  await step(token,700);const angle=(spin?.currentTime||0)/2600*360%360,snap=Math.round(angle/(360/n))*(360/n);spin?.cancel();anim(token,wheel,[{transform:'rotate('+angle+'deg)'},{transform:'rotate('+snap+'deg)'}],{duration:180,easing:'ease-out'});await step(token,190);sfx('hit');sfx('shimmer');shake(token,4,200);caption(token,info.count+' JUSTINS COLLECTED','your collection gift is ready');
  await step(token,950);const book=el('collection-open')?.getBoundingClientRect();if(book){anim(token,wheel,[{transform:'translate(0,0) rotate('+snap+'deg) scale(1)'},{transform:'translate('+(book.x+book.width/2-cx)+'px,'+(book.y+book.height/2-cy)+'px) rotate('+(snap+90)+'deg) scale(.05)',opacity:.4}],{duration:520,easing:'cubic-bezier(.6,0,.4,1)'});at(token,500,()=>{anim(token,el('collection-open'),[{transform:'scale(1)'},{transform:'scale(1.25) rotate(-6deg)'},{transform:'scale(1)'}],{duration:380,fill:'none'});sfx('pop')})}
  for(const c of root.querySelectorAll('.cine-caption'))anim(token,c,[{opacity:1},{opacity:0}],{duration:400,delay:200});anim(token,dark,[{opacity:1},{opacity:0}],{duration:400,delay:250});await step(token,700)}

 /* ---------- community milestone: everyone finishes it (~3.6s) ---------- */
 async function community(token,info){const W=innerWidth,H=innerHeight;if(reduced()){await still(token,'COMMUNITY GOAL!',info.goal.toLocaleString()+' clicks · claim it in Community',1800);return}
  const dark=add(token,'cine-dark soft');anim(token,dark,[{opacity:0},{opacity:1}],{duration:300});
  const meter=add(token,'cine-meter','<small>COMMUNITY CLICKS</small><div class="cine-meter-bar"><i></i><em class="half l"></em><em class="half r"></em></div><b></b>');meter.querySelector('b').textContent=(info.goal-1).toLocaleString()+' / '+info.goal.toLocaleString();const fill=meter.querySelector('i');fill.style.transform='scaleX(.97)';
  const avatars=[...new Set(info.avatars||[])].slice(0,7);while(avatars.length<6)avatars.push(G.skins[Math.floor(rand(0,G.skins.length))].id);const mine=window.justinClicker.skin?.id||'normal',crowd=[...avatars.slice(0,6),mine],mr=meter.getBoundingClientRect(),cx=mr.x+mr.width/2,cy=mr.y+mr.height/2,spots=[];
  crowd.forEach((id,i)=>{const a=Math.PI+i/(crowd.length-1)*Math.PI,x=cx+Math.cos(a)*Math.min(W*.42,300),y=cy+Math.sin(a)*(-Math.min(H*.28,170))-10,p=img(token,face(id),'cine-portrait avatar');spots.push([x,y,p]);anim(token,p,[{transform:'translate3d('+(x+(x<cx?-W:W)*.6)+'px,'+(y+rand(-80,80))+'px,0) translate(-50%,-50%)'},{transform:'translate3d('+x+'px,'+y+'px,0) translate(-50%,-50%)'}],{duration:600,delay:i*60,easing:'cubic-bezier(.2,.8,.3,1.1)'})});
  await step(token,1000);const [mx,my]=spots[spots.length-1],chip=add(token,'cine-plus');chip.textContent='+1';anim(token,chip,[{transform:'translate3d('+mx+'px,'+my+'px,0) translate(-50%,-50%) scale(.6)'},{transform:'translate3d('+((mx+cx)/2)+'px,'+(Math.min(my,cy)-90)+'px,0) translate(-50%,-50%) scale(1.2)',offset:.5},{transform:'translate3d('+cx+'px,'+cy+'px,0) translate(-50%,-50%) scale(.5)',opacity:.4}],{duration:560,easing:'ease-in-out'});
  await step(token,560);anim(token,fill,[{transform:'scaleX(.97)'},{transform:'scaleX(1)'}],{duration:150});meter.querySelector('b').textContent=info.goal.toLocaleString()+' / '+info.goal.toLocaleString();sfx('crack');await step(token,200);meter.classList.add('broken');sfx('hit');sfx('cheer');at(token,300,()=>sfx('fanfare'));shake(token,6,260);
  const points=(el('mini-score')?.classList.contains('show')?el('mini-score'):el('points')).getBoundingClientRect();
  for(let i=0;i<18;i++){const coin=img(token,'assets/icons/coin.svg','cine-coin'),[tx,ty]=i<12?[points.x+points.width/2,points.y+points.height/2]:spots[i%spots.length];anim(token,coin,[{transform:'translate3d('+cx+'px,'+cy+'px,0) scale(.4)'},{transform:'translate3d('+(cx+rand(-160,160))+'px,'+(cy+rand(-140,40))+'px,0) scale(1)',offset:.35},{transform:'translate3d('+tx+'px,'+ty+'px,0) scale(.5)',opacity:.3}],{duration:900,delay:i*25,easing:'cubic-bezier(.3,.7,.5,1)'})}
  at(token,950,()=>{anim(token,el('points'),[{transform:'scale(1)'},{transform:'scale(1.15)'},{transform:'scale(1)'}],{duration:300,fill:'none'});sfx('buy')});caption(token,'COMMUNITY GOAL!',info.goal.toLocaleString()+' clicks · claim it in Community');
  await step(token,1500);anim(token,dark,[{opacity:1},{opacity:0}],{duration:350});for(const e of root.querySelectorAll('.cine-meter,.cine-caption,.cine-portrait'))anim(token,e,[{opacity:1},{opacity:0}],{duration:300});await step(token,360)}

 /* ---------- invasion result card ---------- */
 async function result(token,info){const card=add(token,'cine-result '+(info.cleared?'won':'lost'),'<small></small><b></b><span></span><em></em>');card.querySelector('small').textContent=info.name.toUpperCase();card.querySelector('b').textContent=info.cleared?'INVASION REPELLED':info.caught?'THEY GOT AWAY':'NOBODY WAS CAUGHT';card.querySelector('span').textContent=info.caught+' / '+info.total+' caught'+(info.cleared?' · 3× until it ends':'');card.querySelector('em').textContent=info.next?'Next: '+info.next:'';
  sfx(info.cleared?'fanfare':'deep3');anim(token,card,[{opacity:0,transform:'translate(-50%,-30px) scale(.9)'},{opacity:1,transform:'translate(-50%,0) scale(1)'}],{duration:380,easing:'cubic-bezier(.2,.9,.3,1.3)'});await step(token,2600);anim(token,card,[{opacity:1},{opacity:0,transform:'translate(-50%,-20px)'}],{duration:300});await step(token,320)}

 /* ---------- public API ---------- */
 const quickIntro={swarm:'THEY’RE HERE.',giant:'GIANT JUSTIN',loki:'TIMELINE BROKEN',ufo:'THEY HAVE ARRIVED'};
 window.JustinCinema={
  playing:()=>Boolean(current),
  invasionIntro:(variant,o={})=>run('intro-'+variant,async token=>{if(reduced()){o.onSlam?.();await still(token,quickIntro[variant],'',1100);return}await intros[variant](token,o)}),
  invasionOutro:(variant,o={})=>run('outro-'+variant,async token=>{if(reduced()){await step(token,300);return}await outros[variant](token,o)}),
  result:info=>run('result',token=>result(token,info)),
  tease,
  rebirth:info=>run('rebirth',token=>rebirth(token,info),{block:true}),
  collection:info=>run('collection',token=>collection(token,info),{block:true}),
  community:info=>run('community',token=>community(token,info),{block:true}),
  mothership,preload
 };
})();
